#!/usr/bin/env python3
"""host-deep-equality.py <seed>: DEEP EQUALITY BY THE HOST, OF TYPED OBJECTS AGAINST TYPED AND PLAIN ONES. Each row: a base of one to four properties; one side changed (an undefined property put in first | in the middle | last; a property left out; another value; another order; made non-enumerable; an enumerable | non-enumerable name on the prototype; what one side owns the other inherits; a symbol key; an extra property stored later; frozen; null against undefined; -0 against 0; NaN); each side typed (a literal under a written type | an object of a class) | plain (the same copied by untyped code) | typed with extras; bare | in an array | in a field | in a Map | in a Set | two levels down; asked of Bun.deepEquals loose and strict, util.isDeepStrictEqual, assert.deepEqual | deepStrictEqual | notDeepStrictEqual, BOTH WAYS ROUND."""
import random, sys
seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
R = random.Random(seed)
out = []; w = out.append
w('// generated by host-deep-equality.py %d' % seed)
w('import { isDeepStrictEqual } from "node:util";')
w('import assert from "node:assert";')
w('const plain = (o: any): any => { const r: any = {}; for (const k of Reflect.ownKeys(o)) Object.defineProperty(r, k, Object.getOwnPropertyDescriptor(o, k)!); return Object.setPrototypeOf(r, Object.getPrototypeOf(o) === Object.prototype ? Object.prototype : Object.getPrototypeOf(o)); };')
w('const throws = (f: () => void) => { try { f(); return 0; } catch (e) { return 1; } };')
w('const ask = (a: any, b: any): string => [Bun.deepEquals(a, b), Bun.deepEquals(b, a), Bun.deepEquals(a, b, true), Bun.deepEquals(b, a, true), isDeepStrictEqual(a, b), isDeepStrictEqual(b, a)].map(x => (x ? "1" : "0")).join("") + [throws(() => assert.deepEqual(a, b)), throws(() => assert.deepEqual(b, a)), throws(() => assert.deepStrictEqual(a, b)), throws(() => assert.deepStrictEqual(b, a)), throws(() => assert.notDeepStrictEqual(a, b))].join("");')
w('const sym = Symbol("s");')
VALUES = ['1', '2', '"s"', 'true', 'null', 'undefined', '0', '-0', 'NaN', '[1, 2]', '{ in: 1 }', '1.5']
TYPES = {'1': 'number', '2': 'number', '"s"': 'string', 'true': 'boolean', 'null': 'null', 'undefined': 'undefined', '0': 'number', '-0': 'number', 'NaN': 'number', '[1, 2]': 'number[]', '{ in: 1 }': '{ in: number }', '1.5': 'number'}
def literal(props): return '{ ' + ', '.join('%s: %s' % p for p in props) + ' }' if props else '{}'
def typed(props): return '{ ' + '; '.join('%s: %s' % (n, TYPES[v]) for n, v in props) + ' }' if props else '{}'
n = 0
for row in range(150):
    names = R.sample(['a', 'b', 'c', 'd', 'e'], R.randrange(1, 5)); base = [(x, R.choice(VALUES[:5] + VALUES[9:])) for x in names]
    other = list(base); after = ['', '']; change = R.choice(['undefined first', 'undefined in the middle', 'undefined last', 'two undefined', 'left out', 'another value', 'another order', 'hidden', 'name on the prototype', 'hidden name on the prototype', 'owned against inherited', 'a symbol', 'an undefined symbol', 'an extra', 'an undefined extra', 'frozen', 'null for undefined', 'signed zero', 'the same', 'undefined on both at other places'])
    free = [x for x in ['u', 'v', 'z'] ]
    if change == 'undefined first': other.insert(0, ('u', 'undefined'))
    elif change == 'undefined in the middle': other.insert(len(other) // 2 if len(other) > 1 else 0, ('u', 'undefined'))
    elif change == 'undefined last': other.append(('u', 'undefined'))
    elif change == 'two undefined': other.insert(0, ('u', 'undefined')); other.insert(R.randrange(len(other) + 1), ('v', 'undefined'))
    elif change == 'left out': other.pop(R.randrange(len(other)))
    elif change == 'another value': i = R.randrange(len(other)); other[i] = (other[i][0], R.choice(VALUES))
    elif change == 'another order': other = other[::-1]
    elif change == 'hidden': after[1] = 'Object.defineProperty(Y, "%s", { enumerable: false });' % other[0][0]
    elif change == 'name on the prototype': after[1] = 'Object.setPrototypeOf(Y, { zz: 1 });'
    elif change == 'hidden name on the prototype': after[1] = 'Object.setPrototypeOf(Y, Object.defineProperty({}, "zz", { value: 1, enumerable: false }));'
    elif change == 'owned against inherited': last = other.pop(); after[1] = 'Object.setPrototypeOf(Y, { %s: %s });' % last
    elif change == 'a symbol': after[1] = '(Y as any)[sym] = 1;'
    elif change == 'an undefined symbol': after[1] = '(Y as any)[sym] = undefined;'
    elif change == 'an extra': after[1] = '(Y as any).extra = 1;'; after[0] = R.choice(['', '(X as any).extra = 1;', '(X as any).extra = 2;'])
    elif change == 'an undefined extra': after[1] = '(Y as any).extra = undefined;'
    elif change == 'frozen': after[1] = 'Object.freeze(Y);'; after[0] = R.choice(['', '(X as any).extra = undefined;'])
    elif change == 'null for undefined': other = [(a, 'undefined' if v == 'null' else v) for a, v in other] + [('u', 'null')]; base = base + [('u', 'undefined')]
    elif change == 'signed zero': base = base + [('u', '0')]; other = other + [('u', '-0')]
    elif change == 'undefined on both at other places': base = [('u', 'undefined')] + base; other = other + [('v', 'undefined')]
    kinds = [R.choice(['typed', 'plain', 'typed', 'class', 'extras']) for _ in range(2)]
    if 'setPrototypeOf(Y' in after[1]: kinds[1] = 'plain'  # objects of a declared type keep their prototype, and classes are fixed, under --aot: the name goes on a plain object's prototype
    text = []
    for side, props, kind, more in (('X', base, kinds[0], after[0]), ('Y', other, kinds[1], after[1])):
        v = '%s%d' % (side.lower(), row)
        if kind == 'class':
            w('class %s%d { %s }' % (side, row, ' '.join('%s: %s = %s;' % (a, TYPES[b], b) for a, b in props))); text.append('const %s = new %s%d();' % (v, side, row))
        elif kind == 'plain': text.append('const %s = plain(%s);' % (v, literal(props)))
        else: text.append('const %s: %s = %s;' % (v, typed(props), literal(props)))
        if kind == 'extras': text.append('(%s as any).more = 5;' % v)
        if more: text.append(more.replace(side + '%d.prototype' % row, '@@').replace(side, v).replace('@@', side + '%d.prototype' % row))
    x, y = 'x%d' % row, 'y%d' % row
    wrap = R.choice(['%s', '%s', '%s', '[%s]', '{ f: %s }', 'new Map([["k", %s]])', 'new Set([%s])', '{ f: [{ g: %s }] }', '[0, %s, 1]'])
    w('try { %s console.log("%d %s | %s %s | %s: " + ask(%s, %s)); } catch (e) { console.log("%d %s | %s %s: THROWS " + (e as Error).name); }' % (' '.join(text), row, change, kinds[0], kinds[1], wrap.replace('"', "'") % '_', wrap % x, wrap % y, row, change, kinds[0], kinds[1]))
print('\n'.join(out))
